 public class SessionSettings {
  public string Server="",Client="",ItemFile="",ImageFolder="",SqlHost="",SqlDatabase="",SqlUser="",PasswordCipher="",Language="pt",Account="",Character="",Search="";
  public bool WindowsAuthentication=true,TrustCertificate=false,RememberPassword=false,AutoConnect=true;public int Page=0,Width=1440,Height=900;
  public static string FilePath{get{return Path.Combine(Guard.LocalData,"session-v2.json");}}
  public static SessionSettings Load(){try{string path=FilePath;bool migrate=false;if(!File.Exists(path)&&string.Equals(Path.GetFullPath(Guard.LocalData),Path.GetFullPath(Guard.DefaultLocalData),StringComparison.OrdinalIgnoreCase)){string legacy=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MUCommunityWorkbench","session-v2.json");if(File.Exists(legacy)){path=legacy;migrate=true;}}var settings=new JavaScriptSerializer().Deserialize<SessionSettings>(File.ReadAllText(path))??new SessionSettings();if(migrate)settings.Save();return settings;}catch{return new SessionSettings();}}
  public void Save(){Guard.Atomic(FilePath,Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(this)));}
  public void RememberSecret(string plain){PasswordCipher=RememberPassword&&!string.IsNullOrEmpty(plain)?Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(plain),null,DataProtectionScope.CurrentUser)):"";}
  public string ReadSecret(){if(!RememberPassword||string.IsNullOrEmpty(PasswordCipher))return "";try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(PasswordCipher),null,DataProtectionScope.CurrentUser));}catch{return "";}}
 }
